// =============================================================================
// Node 1: Twilio Missed Call Detection & Status Filtering
// =============================================================================
const body = $input.first().json.body || $input.first().json;

const callSid = body.CallSid || body.DialCallSid || `call_${Date.now()}`;
const fromNumber = body.From || body.Caller || '';
const toNumber = body.To || body.Called || '';
const dialCallStatus = (body.DialCallStatus || body.CallStatus || '').toLowerCase();
const duration = parseInt(body.DialCallDuration || body.CallDuration || '0', 10);

// Identify whether the call was genuinely missed/unanswered
const missedStatuses = ['no-answer', 'busy', 'canceled', 'failed', 'ringing'];
let isMissed = false;
let reason = '';

if (missedStatuses.includes(dialCallStatus)) {
  isMissed = true;
  reason = `Call was unanswered with status: ${dialCallStatus}`;
} else if (dialCallStatus === 'completed' && duration === 0) {
  isMissed = true;
  reason = 'Call completed with 0 duration (unanswered)';
} else {
  isMissed = false;
  reason = `Call was answered or completed (duration: ${duration}s). No SMS needed.`;
}

return [{
  json: {
    call_sid: callSid,
    from_number: fromNumber,
    to_number: toNumber,
    raw_status: dialCallStatus,
    duration: duration,
    is_missed: isMissed,
    reason: reason
  }
}];

// =============================================================================
// Node 3: Multi-Tenant Client Resolution & Automation Settings
// Looks up client organization by the Twilio phone number dialed ('To')
// =============================================================================
const input = $input.first().json;
const toNumber = input.to_number;
const fromNumber = input.from_number;
const callSid = input.call_sid;

// Default / Fallback Client Context for Demonstration & Initial Setup
let orgId = '00000000-0000-0000-0000-000000000001';
let orgName = 'Northside Plumbing & Heating';
let isEnabled = true;
let formUrl = 'https://briksystems.io/#/contact';
let smsTemplate = "Hey, sorry we missed your call at {{business_name}}! We're currently helping another customer, but we'll get back to you ASAP. In the meantime, you can fill out this quick form so we can get details on what you need: {{form_url}}";

return [{
  json: {
    call_sid: callSid,
    organization_id: orgId,
    organization_name: orgName,
    from_number: fromNumber,
    to_number: toNumber,
    missed_call_sms_enabled: isEnabled,
    sms_template: smsTemplate,
    form_url: formUrl,
    business_name: orgName
  }
}];

// =============================================================================
// Node 4: Idempotency & Deduplication Engine
// Ensures a single CallSid NEVER sends more than one automatic SMS
// =============================================================================
const staticData = $getWorkflowStaticData('global');
staticData.processedCallSids = staticData.processedCallSids || [];

const item = $input.first().json;
const callSid = item.call_sid;

let isDuplicate = false;

if (staticData.processedCallSids.includes(callSid)) {
  isDuplicate = true;
  console.log(`[IDEMPOTENCY] CallSid ${callSid} has already triggered an SMS. Skipping duplicate.`);
} else {
  staticData.processedCallSids.push(callSid);
  if (staticData.processedCallSids.length > 5000) {
    staticData.processedCallSids.shift();
  }
}

return [{
  json: {
    ...item,
    is_duplicate: isDuplicate
  }
}];

// =============================================================================
// Node 6: Render Personalized SMS Template
// Replaces variables {{business_name}} and {{form_url}}
// =============================================================================
const item = $input.first().json;

let messageBody = item.sms_template || 'Hey, sorry we missed your call! We will contact you shortly: {{form_url}}';
messageBody = messageBody.replace(/\{\{business_name\}\}/g, item.business_name || 'our team');
messageBody = messageBody.replace(/\{\{form_url\}\}/g, item.form_url || 'https://briksystems.io/#/contact');

const auditLog = `[BRIK MISSED CALL AUTOMATION] Client: ${item.organization_name} (${item.organization_id}) | Caller: ${item.from_number} | Twilio SID: ${item.call_sid} | SMS Text: "${messageBody}"`;
console.log(auditLog);

return [{
  json: {
    ...item,
    rendered_sms_body: messageBody,
    audit_log: auditLog
  }
}];

// =============================================================================
// Node 7: Simulate / Dispatch Twilio SMS & Prepare Database Records
// Generates unique message_sid and formats Supabase insert payloads
// =============================================================================
const item = $input.first().json;
const messageSid = `SM_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// 1. Customer Upsert Payload (Supabase 'customers' table)
const customerRecord = {
  organization_id: item.organization_id,
  name: `Caller ${item.from_number.slice(-4) || 'Customer'}`,
  phone: item.from_number,
  source: 'Missed Call',
  last_call_at: new Date().toISOString(),
  call_status: 'missed'
};

// 2. Call Record Payload (Supabase 'calls' table)
const callRecord = {
  organization_id: item.organization_id,
  from_number: item.from_number,
  to_number: item.to_number,
  direction: 'inbound',
  call_status: 'no-answer',
  twilio_call_sid: item.call_sid,
  sms_sent: true,
  timestamp: new Date().toISOString()
};

// 3. Message Record Payload (Supabase 'messages' table)
const messageRecord = {
  organization_id: item.organization_id,
  from_number: item.to_number,
  to_number: item.from_number,
  message_body: item.rendered_sms_body,
  message_type: 'MISSED_CALL',
  direction: 'OUTBOUND',
  status: 'SENT',
  twilio_message_sid: messageSid,
  timestamp: new Date().toISOString()
};

return [{
  json: {
    success: true,
    action: 'missed_call_sms_dispatched',
    organization_id: item.organization_id,
    organization_name: item.organization_name,
    recipient_phone: item.from_number,
    twilio_phone: item.to_number,
    twilio_call_sid: item.call_sid,
    twilio_message_sid: messageSid,
    sms_content: item.rendered_sms_body,
    supabase_payloads: {
      customer: customerRecord,
      call: callRecord,
      message: messageRecord
    }
  }
}];

